import{_ as s,C as l,o as a,c as r,a2 as e,b as o,w as t,a as A,E as n,a3 as p}from"./chunks/framework.RycU2wFZ.js";const u=JSON.parse('{"title":"办公协同与人在回路 (HITL) 审批规范","description":"","frontmatter":{},"headers":[],"relativePath":"security-hitl/hitl-approval.md","filePath":"security-hitl/hitl-approval.md"}'),d={name:"security-hitl/hitl-approval.md"};function h(B,E,c,g,k,C){const i=l("Mermaid");return a(),r("div",null,[E[1]||(E[1]=e('<h1 id="办公协同与人在回路-hitl-审批规范" tabindex="-1">办公协同与人在回路 (HITL) 审批规范 <a class="header-anchor" href="#办公协同与人在回路-hitl-审批规范" aria-label="Permalink to &quot;办公协同与人在回路 (HITL) 审批规范&quot;">​</a></h1><blockquote><p><strong>版本</strong>：v2.0.0 (企业级生产规范)<br><strong>状态</strong>：<strong>已定稿 (Approved Specification)</strong><br><strong>适用范围</strong>：飞书/企业微信/钉钉审批机器人、HTTP 402 异步挂起引擎、移动端一键放行与客户端自动重放<br><strong>核心定位</strong>：<strong>企业级 AI 行为审计与资金防火墙网关 (AI Agent Gateway &amp; FinOps)</strong></p></blockquote><hr><h2 id="_1-痛点背景与设计目标" tabindex="-1">1. 痛点背景与设计目标 <a class="header-anchor" href="#_1-痛点背景与设计目标" aria-label="Permalink to &quot;1. 痛点背景与设计目标&quot;">​</a></h2><p>在真实企业生产场景中，大语言模型与自主智能体（AI Agent）接入高价值外部资源（如商业大模型、万方学术、企查查深度征信、短信核验通道）时，面临关键安全盾牌缺失：</p><ol><li><strong>粗暴一刀切阻断</strong>：传统策略引擎一旦检测到请求超过阈值，直接报错拒绝（<code>SINGLE_TX_CAP_EXCEEDED</code>），中断了正常的企业自动化业务流；</li><li><strong>长连接阻塞雪崩</strong>：若在网关反向代理长连接中同步等待管理员人工审批，耗时通常长达数分钟，会导致网关 Goroutine 耗尽与 HTTP 连接池雪崩；</li><li><strong>缺乏移动办公协同</strong>：企业负责人无法随时随地在手机端感知 Agent 的高额消费意图并快速决议。</li></ol><p>为此，AgentFinOps 提出<strong>三级风控梯度</strong>与 <strong>HTTP 402 异步挂起/解挂机制</strong>。</p><hr><h2 id="_2-三级风控梯度-three-tier-risk-policy" tabindex="-1">2. 三级风控梯度 (Three-Tier Risk Policy) <a class="header-anchor" href="#_2-三级风控梯度-three-tier-risk-policy" aria-label="Permalink to &quot;2. 三级风控梯度 (Three-Tier Risk Policy)&quot;">​</a></h2><p>网关根据请求预估金额 $\\Delta$，原子判定执行策略：</p><p>$$\\begin{cases} \\Delta \\le \\text{hitl_threshold} &amp; \\Longrightarrow \\text{小额免审：策略引擎毫秒级极速放行} \\ \\text{hitl_threshold} &lt; \\Delta \\le \\text{max_tx_cap} &amp; \\Longrightarrow \\text{中大额审批：触发 402 异步挂起并推送飞书/企微卡片} \\ \\Delta &gt; \\text{max_tx_cap} &amp; \\Longrightarrow \\text{超大额阻断：单笔硬顶拒绝 (SINGLE_TX_CAP_EXCEEDED)} \\end{cases}$$</p><ul><li><strong>免审额度 (<code>hitl_threshold</code>)</strong>：例如 $\\le 1.00$ 元，日常微额调用毫秒级放行；</li><li><strong>审批区间 (<code>(hitl_threshold, max_tx_cap]</code>)</strong>：例如 $1.00$ 元至 $100.00$ 元，触发人在回路；</li><li><strong>单笔硬顶 (<code>max_tx_cap</code>)</strong>：例如 $&gt; 100.00$ 元，硬性拦截，防御极端 Prompt 注入。</li></ul><hr><h2 id="_3-402-异步挂起与解挂时序-sequence-flow" tabindex="-1">3. 402 异步挂起与解挂时序 (Sequence Flow) <a class="header-anchor" href="#_3-402-异步挂起与解挂时序-sequence-flow" aria-label="Permalink to &quot;3. 402 异步挂起与解挂时序 (Sequence Flow)&quot;">​</a></h2>',14)),(a(),o(p,null,{default:t(()=>[n(i,{id:"mermaid-66",class:"mermaid",graph:"sequenceDiagram%0A%20%20%20%20autonumber%0A%20%20%20%20actor%20Agent%20as%20AI%20Agent%20(Client%20SDK)%0A%20%20%20%20participant%20GW%20as%20Go%20Gateway%0A%20%20%20%20participant%20Collab%20as%20%E9%A3%9E%E4%B9%A6%20%2F%20%E4%BC%81%E4%B8%9A%E5%BE%AE%E4%BF%A1%20%2F%20%E9%92%89%E9%92%89%0A%20%20%20%20actor%20Approver%20as%20%E4%B8%9A%E5%8A%A1%E8%B4%9F%E8%B4%A3%E4%BA%BA%20(%E6%89%8B%E6%9C%BA%E7%A7%BB%E5%8A%A8%E7%AB%AF)%0A%20%20%20%20participant%20Upstream%20as%20%E4%B8%8A%E6%B8%B8%E5%95%86%E4%B8%9A%20API%20%2F%20%E6%A8%A1%E5%9E%8B%E6%9C%8D%E5%8A%A1%0A%0A%20%20%20%20Agent-%3E%3EGW%3A%201.%20%E5%8F%91%E8%B5%B7%E9%AB%98%E9%A2%9D%E8%AF%B7%E6%B1%82%20POST%20%2Fv1%2Ftools%2Fcall%0A%20%20%20%20GW-%3E%3EGW%3A%202.%20%E5%91%BD%E4%B8%AD%E4%B8%AD%E5%A4%A7%E9%A2%9D%E5%AE%A1%E6%89%B9%E5%8C%BA%E9%97%B4%EF%BC%8C%E7%94%9F%E6%88%90%20approval_id%20(%E7%8A%B6%E6%80%81%3A%20pending)%0A%20%20%20%20GW-%3E%3ECollab%3A%203.%20%E5%BC%82%E6%AD%A5%E6%8E%A8%E9%80%81%E4%BA%A4%E4%BA%92%E5%BC%8F%E5%AE%A1%E6%89%B9%E5%8D%A1%E7%89%87%20(Agent%E5%90%8D%E7%A7%B0%E3%80%81%E6%84%8F%E5%9B%BE%E3%80%81%E9%A2%84%E4%BC%B0%E9%87%91%E9%A2%9D%E3%80%81%E6%89%80%E5%B1%9E%E9%83%A8%E9%97%A8)%0A%20%20%20%20GW--%3E%3EAgent%3A%204.%20HTTP%20402%20Payment%20Required%3Cbr%2F%3E%7B%22error%22%3A%20%22APPROVAL_REQUIRED%22%2C%20%22approval_id%22%3A%20%22appr_xxx%22%2C%20%22retry_after%22%3A%205%7D%0A%20%20%20%20%0A%20%20%20%20Note%20over%20Agent%3A%20Client%20SDK%20%E8%BF%9B%E5%85%A5%E4%BC%98%E9%9B%85%E7%AD%89%E5%BE%85%E7%8A%B6%E6%80%81%EF%BC%8C%E9%80%80%E9%81%BF%E8%BD%AE%E8%AF%A2%E7%BD%91%E5%85%B3%E5%AE%A1%E6%89%B9%E7%8A%B6%E6%80%81...%0A%20%20%20%20Collab--%3E%3EApprover%3A%205.%20%E6%89%8B%E6%9C%BA%E7%AB%AF%E5%BC%B9%E5%87%BA%E5%AF%8C%E6%96%87%E6%9C%AC%E5%AE%A1%E6%89%B9%E5%8D%A1%E7%89%87%E9%80%9A%E7%9F%A5%0A%20%20%20%20Approver-%3E%3ECollab%3A%206.%20%E5%AE%A1%E6%9F%A5%E6%84%8F%E5%9B%BE%EF%BC%8C%E7%82%B9%E5%87%BB%E3%80%90%E6%89%B9%E5%87%86%E6%94%BE%E8%A1%8C%E3%80%91%0A%20%20%20%20Collab-%3E%3EGW%3A%207.%20Webhook%20%E5%AE%A1%E6%89%B9%E5%9B%9E%E8%B0%83%20(%E6%90%BA%E5%B8%A6%E5%AE%89%E5%85%A8%E7%AD%BE%E5%90%8D%E4%B8%8E%E6%93%8D%E4%BD%9C%E4%BA%BA%E8%BA%AB%E4%BB%BD)%0A%20%20%20%20GW-%3E%3EGW%3A%208.%20%E9%AA%8C%E7%AD%BE%E9%80%9A%E8%BF%87%EF%BC%8CCAS%20%E5%8E%9F%E5%AD%90%E7%BD%AE%E4%B8%BA%20approved%20(%E9%98%B2%E9%87%8D%E5%A4%8D%E5%86%B3%E8%AE%AE)%0A%20%20%20%20%0A%20%20%20%20Agent-%3E%3EGW%3A%209.%20%E6%90%BA%E5%B8%A6%20X-AgentPay-Approval-Id%3A%20appr_xxx%20%E9%87%8D%E6%94%BE%E8%AF%B7%E6%B1%82%0A%20%20%20%20GW-%3E%3EGW%3A%2010.%20%E6%A0%A1%E9%AA%8C%20approval%20%E7%8A%B6%E6%80%81%E4%B8%BA%20approved%EF%BC%8C%E6%A0%B8%E9%94%80%E5%87%AD%E8%AF%81%20(consumed)%0A%20%20%20%20GW-%3E%3EGW%3A%2011.%20%E5%8E%9F%E5%AD%90%E6%89%A7%E8%A1%8C%E5%86%85%E9%83%A8%E8%B4%A6%E6%9C%AC%20Hold%20%E9%94%81%E5%AE%9A%E9%85%8D%E9%A2%9D%0A%20%20%20%20GW-%3E%3EUpstream%3A%2012.%20%E8%BD%AC%E5%8F%91%E8%AF%B7%E6%B1%82%E8%87%B3%E4%B8%8A%E6%B8%B8%0A%20%20%20%20Upstream--%3E%3EGW%3A%2013.%20%E8%BF%94%E5%9B%9E%E6%89%A7%E8%A1%8C%E7%BB%93%E6%9E%9C%0A%20%20%20%20GW-%3E%3EGW%3A%2014.%20%E8%B4%A6%E6%9C%AC%E7%A1%AE%E6%89%A3%20(Capture)%EF%BC%8C%E5%86%99%E5%85%A5%E4%B8%8D%E5%8F%AF%E5%8F%98%E5%AE%A1%E8%AE%A1%E6%B5%81%E6%B0%B4%0A%20%20%20%20GW--%3E%3EAgent%3A%2015.%20200%20OK%20(%E6%89%A7%E8%A1%8C%E7%BB%93%E6%9E%9C%20%2B%20%E6%89%A3%E6%AC%BE%E5%87%AD%E6%8D%AE)%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[A(" Loading... ",-1)])]),_:1})),E[2]||(E[2]=e(`<hr><h2 id="_4-协同审批卡片规范" tabindex="-1">4. 协同审批卡片规范 <a class="header-anchor" href="#_4-协同审批卡片规范" aria-label="Permalink to &quot;4. 协同审批卡片规范&quot;">​</a></h2><h3 id="_4-1-飞书互动卡片-feishu-cardkit-2-0" tabindex="-1">4.1 飞书互动卡片 (Feishu CardKit 2.0) <a class="header-anchor" href="#_4-1-飞书互动卡片-feishu-cardkit-2-0" aria-label="Permalink to &quot;4.1 飞书互动卡片 (Feishu CardKit 2.0)&quot;">​</a></h3><p>卡片包含完整的审计上下文：</p><ul><li><strong>标题</strong>：<code>⚠️ AI Agent 大额调用审批申请</code></li><li><strong>内容字段</strong>： <ul><li><strong>智能体标识</strong>：<code>Coding Copilot (agent_01)</code></li><li><strong>归属部门 / 项目</strong>：<code>研发事业群 / 代码智能体项目组</code></li><li><strong>调用意图 / 目标</strong>：<code>查询全国企业深度工商涉诉征信报告</code></li><li><strong>预估扣款金额</strong>：<code>¥ 30.00 元</code></li><li><strong>当前申请时间</strong>：<code>2026-11-07 18:30:00</code></li><li><strong>有效倒计时</strong>：<code>剩余 300 秒自动失效</code></li></ul></li><li><strong>操作按钮</strong>： <ul><li>【批准放行】（绿色主按钮，附带安全二次确认）</li><li>【驳回调用】（红色警告按钮，可填选驳回理由）</li></ul></li></ul><h3 id="_4-2-企业微信审批卡片-wecom-template-card" tabindex="-1">4.2 企业微信审批卡片 (WeCom Template Card) <a class="header-anchor" href="#_4-2-企业微信审批卡片-wecom-template-card" aria-label="Permalink to &quot;4.2 企业微信审批卡片 (WeCom Template Card)&quot;">​</a></h3><p>通过企业微信应用消息推送模版卡片，支持移动端消息免密直按，并实时更新卡片按钮状态为“已批准”或“已驳回”，防止多人重复决议。</p><hr><h2 id="_5-安全决策与防重放机制-security-idempotency" tabindex="-1">5. 安全决策与防重放机制 (Security &amp; Idempotency) <a class="header-anchor" href="#_5-安全决策与防重放机制-security-idempotency" aria-label="Permalink to &quot;5. 安全决策与防重放机制 (Security &amp; Idempotency)&quot;">​</a></h2><ol><li><strong>回调强制官方验签</strong>： <ul><li>飞书：校验 <code>X-Lark-Signature</code> 与时间戳；</li><li>企业微信：采用 <code>AES-CBC-256</code> 解密并验证回调 <code>MsgSignature</code>；</li><li>校验请求时间戳差值 $\\le 300$ 秒，防重放攻击。</li></ul></li><li><strong>审批人 RBAC 权限严格校验</strong>： <ul><li>检查点击审批人的工号/邮箱，必须具备该租户对应项目的 <code>owner</code> 或 <code>admin</code> 权限，普通员工无权放行。</li></ul></li><li><strong>CAS 单次状态迁移 (Compare-And-Swap)</strong>： <ul><li>审批单通过数据库条件更新：<div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">UPDATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ap_approval_request </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">SET</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;approved&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, decided_by </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $user_id, decided_at </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> CURRENT_TIMESTAMP </span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">WHERE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> approval_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> $approval_id </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">AND</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> status</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;pending&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div></li><li>杜绝网络重发或并发点击导致的重复决议。</li></ul></li><li><strong>两阶段资金分离</strong>： <ul><li>负责人点击“批准”仅签发授权许可，<strong>不提前扣款</strong>；</li><li>客户端携带 <code>approval_id</code> 重放时，网关核销凭单并原子执行 <code>Hold -&gt; Capture</code>，若客户端已超时放弃，不会产生任何误扣款。</li></ul></li></ol>`,10))])}const F=s(d,[["render",h]]);export{u as __pageData,F as default};
